   data km_e(1:108) / &
      0, 0, 2, 1, 1, 0, 0, 1, 1, 0, 1, 2, 1, 0, 1, 0, &
      2, 0, 0, 3, 2, 0, 0, 1, 0, 0, 2, 3, 1, 0, 0, 3, &
      1, 0, 1, 4, 2, 0, 0, 5, 0, 0, 2, 5, 1, 0, 0, 5, &
      1, 0, 1, 6, 2, 0, 0, 7, 0, 0, 2, 0, 1, 0, 0, 0, &
      1, 0, 1, 1, 2, 0, 0, 2, 2, 0, 0, 0, 0, 0, 2, 2, &
